package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.TypedFields.require;
import java.util.*;
import java.sql.SQLException;

/** Restricted directory Users adapter. Authority and mapping remain local and explicit. */
final class Scim {
 static final String USER="urn:ietf:params:scim:schemas:core:2.0:User",PATCH="urn:ietf:params:scim:api:messages:2.0:PatchOp",ERROR="urn:ietf:params:scim:api:messages:2.0:Error";
 private Scim() {}
 static Object decode(String contentType,byte[] input) {
  if(input.length>65536)throw new Failure(413,"Directory body exceeds 64 KiB");if(!Set.of("application/scim+json","application/json").contains(Objects.toString(contentType,"").split(";",2)[0].strip().toLowerCase(Locale.ROOT)))throw new Failure(415,"SCIM JSON content type required");
  try{return tools.jackson.databind.json.JsonMapper.builder().enable(tools.jackson.core.StreamReadFeature.STRICT_DUPLICATE_DETECTION).build().readValue(input,Object.class);}catch(tools.jackson.core.JacksonException invalid){throw new Failure(400,"Invalid directory JSON body");}
 }
 static String prefix(String source){return "/api/openservice/scim/"+source+"/v2/Users";}
 static Map<String,Object> fields(Object value){var out=new LinkedHashMap<String,Object>();object(value).forEach((key,item)->{String normalized=key.toLowerCase(Locale.ROOT);require(!out.containsKey(normalized),"Duplicate case-insensitive attribute");out.put(normalized,item);});return out;}
 static Map<String,Object> source(Store.Db db,String id)throws SQLException {var row=db.one("SELECT * FROM os_directory WHERE source_id=?",id);if(row==null)throw new Failure(404,"Directory not found");return row;}
 static Map<String,Object> page(Store.Db db)throws SQLException {
  Service.requireAccountAdministrator(db,db.viewerId);return map("sources",db.all("SELECT source_id,name,role,definition,owner_id,enabled,revision FROM os_directory ORDER BY name,source_id"));
 }
 static Map<String,Object> manage(Store.Db db,String id,Object input)throws Exception {
  Service.requireAccountAdministrator(db,db.viewerId);var body=object(input);String token="",operation;
  if(id.isEmpty()){
   require(body.keySet().equals(Set.of("name","role","groups")),"Provide directory name, role and groups");String name=WorkJobs.text(body.get("name"),80),role=WorkJobs.text(body.get("role"),20);require(Set.of("agent","reader","requester").contains(role),"Directory cannot grant administrator access");require(body.get("groups") instanceof List<?>,"Groups must be a list");var groups=(List<?>)body.get("groups");require(groups.size()<=100,"At most 100 groups are supported");require(new HashSet<>(groups).size()==groups.size(),"Groups must be unique");for(var group:groups)Service.readRecord(db,"sys_user_group",WorkJobs.text(group,32));require(db.count("SELECT COUNT(*) FROM os_directory")<20,"At most 20 directory sources are supported");id=Values.id();operation="created";token="osc_"+Passwords.token();
   db.update("INSERT INTO os_directory(source_id,name,role,definition,owner_id,owner_revision,token_hash,enabled,revision) VALUES(?,?,?,?,?,?,?,1,1)",id,name,role,JSON.writeValueAsString(map("groups",groups)),db.viewerId,db.one("SELECT auth_revision FROM os_user WHERE user_id=?",db.viewerId).get("auth_revision"),Passwords.tokenHash(token));
  }else{
   require(body.keySet().equals(Set.of("operation","revision")),"Provide operation and current revision");operation=WorkJobs.text(body.get("operation"),20);require(Set.of("rotate","disable").contains(operation),"Choose rotate or disable");var current=source(db,id);if(!current.get("revision").toString().equals(Objects.toString(body.get("revision"),"")))throw new Failure(409,"Directory changed; reload before managing its credential");
   boolean enabled=operation.equals("rotate");if(enabled)token="osc_"+Passwords.token();db.update("UPDATE os_directory SET owner_id=?,owner_revision=?,token_hash=?,enabled=?,revision=revision+1 WHERE source_id=?",db.viewerId,db.one("SELECT auth_revision FROM os_user WHERE user_id=?",db.viewerId).get("auth_revision"),Passwords.tokenHash(token),enabled?1:0,id);
  }
  SecurityEvents.record(db,db.viewerId,"","directory."+operation,map("source_id",id));return map("source_id",id,"token",token,"revision",source(db,id).get("revision"));
 }
 static Map<String,Object> authenticate(Store.Db db,String id,String authorization)throws Exception {
  if(db.postgres)db.all("SELECT pg_advisory_xact_lock(18439,4)");String token=Objects.toString(authorization,"");if(!token.matches("Bearer osc_[A-Za-z0-9_-]{32}"))throw new Failure(401,"Directory bearer credential required");
  var source=db.one("SELECT * FROM os_directory WHERE source_id=? AND enabled=1 AND token_hash=?",id,Passwords.tokenHash(token.substring(7)));if(source==null)throw new Failure(401,"Invalid directory credential");
  var owner=db.one("SELECT user_id,role FROM os_user WHERE user_id=? AND auth_revision=? AND active=1 AND role='admin' AND password_reset_required=0",source.get("owner_id"),source.get("owner_revision"));if(owner==null)throw new Failure(401,"Directory authorization changed; an administrator must rotate the credential");db.viewerId=owner.get("user_id").toString();db.viewerRole=owner.get("role").toString();return source;
 }
 static Map<String,Object> identity(Store.Db db,String source,String id)throws SQLException {
  var row=db.one("SELECT u.user_id,u.name,u.active,u.role,u.api_only,i.external_id FROM os_identity i JOIN os_user u ON u.user_id=i.user_id WHERE i.source=? AND i.user_id=?","scim:"+source,id);if(row==null)throw new Failure(404,"Directory user not found");if(row.get("role").equals("admin") || ((Number)row.get("api_only")).intValue()==1)throw new Failure(403,"Locally elevated or API-only accounts need administrator reconciliation");return row;
 }
 static Map<String,Object> resource(Map<String,Object> row,String source,String origin){String id=row.get("user_id").toString();return map("schemas",List.of(USER),"id",id,"userName",row.get("name"),"externalId",row.get("external_id"),"active",((Number)row.get("active")).intValue()==1,"meta",map("resourceType","User","location",origin+prefix(source)+"/"+id));}
 static Map<String,Object> listing(Store.Db db,String source,Map<String,String> args,String origin)throws Exception {
  require(Set.of("startIndex","count","filter").containsAll(args.keySet()),"Unsupported directory query parameter");int start=Math.max(1,Service.number(args.getOrDefault("startIndex","1"),Integer.MIN_VALUE,Integer.MAX_VALUE)),count=Math.max(0,Math.min(100,Service.number(args.getOrDefault("count","100"),Integer.MIN_VALUE,Integer.MAX_VALUE)));String where="i.source=?";var parameters=new ArrayList<Object>();parameters.add("scim:"+source);
  if(args.containsKey("filter")) {String raw=WorkJobs.text(args.get("filter"),400);var filter=java.util.regex.Pattern.compile("(?i)(userName|externalId)\\s+eq\\s+(\"(?:[^\"\\\\]|\\\\.)*\")").matcher(raw);require(filter.matches(),"Only userName or externalId equality filters are supported");String value;try{value=JSON.readValue(filter.group(2),String.class);}catch(tools.jackson.core.JacksonException invalid){throw new Failure(400,"Invalid filter string");}if(filter.group(1).equalsIgnoreCase("userName")){where+=" AND lower(u.name)=?";value=value.toLowerCase(Locale.ROOT);}else where+=" AND i.external_id=?";parameters.add(value);}
  String from=" FROM os_identity i JOIN os_user u ON u.user_id=i.user_id WHERE "+where;long total=db.count("SELECT COUNT(*)"+from,parameters.toArray());parameters.add(count);parameters.add(start-1);var resources=new ArrayList<Object>();for(var row:db.all("SELECT i.user_id"+from+" ORDER BY i.user_id LIMIT ? OFFSET ?",parameters.toArray()))resources.add(resource(identity(db,source,row.get("user_id").toString()),source,origin));return map("schemas",List.of("urn:ietf:params:scim:api:messages:2.0:ListResponse"),"totalResults",total,"startIndex",start,"itemsPerPage",resources.size(),"Resources",resources);
 }
 static Map<String,Object> user(Object input){var body=fields(input);require(Set.of("schemas","username","externalid","active","id","meta").containsAll(body.keySet()),"Unsupported user attribute; roles, passwords and groups stay local");require(List.of(USER).equals(body.get("schemas")),"Provide the supported core User schema");String name=WorkJobs.text(body.get("username"),80),external=WorkJobs.text(body.get("externalid"),160);require(name.matches("[A-Za-z0-9]{1,80}"),"Use an ASCII alphanumeric username");Object active=body.getOrDefault("active",true);require(active instanceof Boolean,"Active must be boolean");return map("name",name,"external",external,"active",active);}
 static boolean patch(Object input,boolean active){var body=fields(input);require(body.keySet().equals(Set.of("schemas","operations")),"Provide schemas and Operations");require(List.of(PATCH).equals(body.get("schemas")),"Provide the PatchOp schema");require(body.get("operations") instanceof List<?>,"Operations must be a list");var operations=(List<?>)body.get("operations");require(!operations.isEmpty() && operations.size()<=20,"Provide 1 to 20 operations");for(var item:operations){var operation=fields(item);require(Set.of("op","path","value").containsAll(operation.keySet()),"Unsupported operation attribute");String op=WorkJobs.text(operation.get("op"),20);require(Set.of("add","replace").contains(op.toLowerCase(Locale.ROOT)),"Only add or replace active is supported");Object value;if(operation.containsKey("path")){require("active".equalsIgnoreCase(WorkJobs.text(operation.get("path"),80)),"Only active can be patched");value=operation.get("value");}else{var values=fields(operation.get("value"));require(values.keySet().equals(Set.of("active")),"Only active can be patched");value=values.get("active");}require(value instanceof Boolean,"Active must be boolean");active=(Boolean)value;}return active;}
 static Map<String,Object> write(Store.Db db,Map<String,Object> source,String id,String method,Object input,String origin)throws Exception {
  String sourceId=source.get("source_id").toString(),namespace="scim:"+sourceId;Map<String,Object> values;
  if(id.isEmpty()){
   values=user(input);if(db.count("SELECT COUNT(*) FROM os_user WHERE lower(name)=?",values.get("name").toString().toLowerCase(Locale.ROOT))>0 || db.count("SELECT COUNT(*) FROM os_identity WHERE source=? AND external_id=?",namespace,values.get("external"))>0)throw new Failure(409,"Directory identity or username already exists");require(db.count("SELECT COUNT(*) FROM os_identity WHERE source=?",namespace)<1000,"Directory reached its 1000-identity limit");
  }else{
   var current=identity(db,sourceId,id);if(method.equals("PATCH"))values=map("name",current.get("name"),"external",current.get("external_id"),"active",patch(input,((Number)current.get("active")).intValue()==1));else{values=user(input);require(values.get("name").equals(current.get("name")) && values.get("external").equals(current.get("external_id")),"Bound username and external ID are immutable");}
  }
  var synced=IdentityProvisioning.synchronize(db,db.viewerId,map("source",namespace,"external_id",values.get("external"),"username",values.get("name"),"role",source.get("role"),"active",values.get("active"),"groups",object(source.get("definition")).get("groups")));String target=object(synced.get("account")).get("user_id").toString();SecurityEvents.record(db,db.viewerId,target,"directory.synchronized",map("source_id",sourceId,"active",values.get("active")));return resource(identity(db,sourceId,target),sourceId,origin);
 }
}
